diff --git a/crates/ignore/src/walk.rs b/crates/ignore/src/walk.rs
index f04f53a..1ecd645 100644
--- a/crates/ignore/src/walk.rs
+++ b/crates/ignore/src/walk.rs
@@ -2360,6 +2360,77 @@ mod tests {
         );
     }

+    #[test]
+    fn git_exclude_linked_worktree() {
+        let td = tmpdir();
+        let git_dir = td.path().join("repo/.git");
+        let worktree_git_dir = git_dir.join("worktrees/linked");
+        let root = td.path().join("linked");
+        mkdirp(git_dir.join("info"));
+        mkdirp(&worktree_git_dir);
+        mkdirp(root.join("sub"));
+        wfile(git_dir.join("info/exclude"), "foo\n");
+        wfile(
+            root.join(".git"),
+            &format!("gitdir: {}\n", worktree_git_dir.display()),
+        );
+        wfile(root.join("foo"), "");
+        wfile(root.join("bar"), "");
+        wfile(root.join("sub/foo"), "");
+        wfile(root.join("sub/bar"), "");
+
+        for commondir in ["../..", git_dir.to_str().unwrap()] {
+            wfile(worktree_git_dir.join("commondir"), commondir);
+            for require_git in [true, false] {
+                for git_exclude in [true, false] {
+                    let mut builder = WalkBuilder::new(&root);
+                    builder
+                        .parents(false)
+                        .git_global(false)
+                        .require_git(require_git)
+                        .git_exclude(git_exclude);
+                    let expected: &[&str] = if git_exclude {
+                        &["bar", "sub", "sub/bar"]
+                    } else {
+                        &["bar", "foo", "sub", "sub/bar", "sub/foo"]
+                    };
+                    assert_paths(&root, &builder, expected);
+                }
+            }
+        }
+    }
+
+    #[test]
+    fn git_exclude_ordinary_directory() {
+        let td = tmpdir();
+        mkdirp(td.path().join("sub"));
+        wfile(td.path().join("foo"), "");
+        wfile(td.path().join("sub/foo"), "");
+
+        for has_git in [false, true] {
+            if has_git {
+                mkdirp(td.path().join(".git/info"));
+                wfile(td.path().join(".git/info/exclude"), "foo\n");
+            }
+            for require_git in [true, false] {
+                for git_exclude in [true, false] {
+                    let mut builder = WalkBuilder::new(td.path());
+                    builder
+                        .parents(false)
+                        .git_global(false)
+                        .require_git(require_git)
+                        .git_exclude(git_exclude);
+                    let expected: &[&str] = if has_git && git_exclude {
+                        &["sub"]
+                    } else {
+                        &["foo", "sub", "sub/foo"]
+                    };
+                    assert_paths(td.path(), &builder, expected);
+                }
+            }
+        }
+    }
+
